For future readers, I created a small python script to do some more advanced postgres export for me which I was able to import into CockroachDB using `AVRO DATA`.

It only handles the types I have in have postgres, so make sure to adapt it to your needs

```python
import psycopg2
import os
import json


def build_avro_type(pg_type_name, nullable):
    avro_type = None

    if pg_type_name.startswith('_'):
        avro_type = {'type': 'array', 'items': build_avro_type(pg_type_name[1:], False)}
    else:
        if pg_type_name in ['uuid', 'text', 'char', 'varchar', 'timestamp', 'timestamptz', 'json', 'jsonb']:
            avro_type = 'string'
        elif pg_type_name == 'bool':
            avro_type = 'boolean'
        elif pg_type_name in ['int4', 'int8']:
            avro_type = 'int'
        else:
            raise Exception(f'unknown type: {pg_type_name}')

    if nullable:
        avro_type = ['null', avro_type]

    return avro_type


def build_avro_schema(table_name, column_definitions):
    schema = {
        'type': 'record',
        'name': table_name,
        'fields': []
    }

    for column_definition in column_definitions:
        schema['fields'].append({
            'name': column_definition[0],
            'type': build_avro_type(column_definition[1], column_definition[2] == 'YES')
        })

    return schema


def build_select_for_avro_type(field_name, avro_type):
    s = None

    if isinstance(avro_type, list) and avro_type[0] == 'null':
        s = f'CASE WHEN {field_name} IS NULL THEN NULL '
        s += f'ELSE json_build_object(\'{avro_type[1]}\', '
        s += build_select_for_avro_type(field_name, avro_type[1])
        s += ') END'
    else:
        if isinstance(avro_type, dict):# only handled for array of simple types
            s = field_name
        elif avro_type == 'string':
            s = f'{field_name}::text'
        elif avro_type == 'boolean':
            s = f'{field_name}::bool'
        elif avro_type == 'int':
            s = f'{field_name}::bigint'
        else:
            raise Exception(f'unknown type: {avro_type}')

    return s


def build_select_for_avro_schema(avro_schema):
    params = []

    for field in avro_schema['fields']:
        field_name = field['name']
        field_type = field['type']

        params.append(f'\'{field_name}\'')
        params.append(build_select_for_avro_type(field_name, field_type))

    s = ','.join(params)

    return f'json_build_object({s})::text'


if __name__ == '__main__':
    backup_path = os.environ['PG_BACKUP_PATH']
    conn = psycopg2.connect(dbname=os.environ['PGDATABASE'], user=os.environ['PGUSER'], password=os.environ['PGPASSWORD'], host=os.environ['PGHOST'], port=os.environ['PGPORT'])

    try:
        with conn:
            with conn.cursor() as curs:
                curs.execute('SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname = %s', ['public'])
                table_names = [row[0] for row in curs]

                for table_name in table_names:
                    curs.execute('SELECT column_name, udt_name, is_nullable FROM information_schema.columns WHERE table_schema = %s and table_name = %s', ['public', table_name])

                    avro_schema = build_avro_schema(table_name, [row for row in curs])
                    select = build_select_for_avro_schema(avro_schema)

                    print(avro_schema)
                    print(select)
                    print('-----------')

                    with open(f'{backup_path}/tables/{table_name}.json', 'w') as f:
                        curs.execute(f'SELECT {select} FROM {table_name}')

                        for row in curs:
                            f.write(row[0])
                            f.write('\n')

                    with open(f'{backup_path}/tables/{table_name}_schema.json', 'w') as f:
                        json.dump(avro_schema, f, indent='\t')
    finally:
        conn.close()

```

My backup script also automatically uploads the created files to S3.

Using the files generated by this script I was able to import the data using commands like this:

```sql
IMPORT INTO my_table
    AVRO DATA ( 's3 presigned url for my_table.json' )
WITH
    data_as_json_records,
    schema_uri = 's3 presigned url for my_table_schema.json'
;
```

I used the following simple Java program to import the data for all tables:

```java
import com.amazonaws.regions.Regions;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3Client;

import java.sql.*;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;

class Scratch {

    private static final String BUCKET = "my-s3-bucket-name";
    private static final String PREFIX = "my/s3/bucket/prefix/";
    private static final List<String> TABLES = List.of(
            "my_table",
            "another_table"
    );

    public static void main(String[] args) throws Exception {
        final AmazonS3 s3 = AmazonS3Client.builder()
                .withRegion(Regions.EU_CENTRAL_1)
                .build();
        
        final List<String> errors = new ArrayList<>();

        try (Connection conn = DriverManager.getConnection("cockroach jdbc url", "user", "password")) {
            final Date expiration = new Date(System.currentTimeMillis() + Duration.ofMinutes(15L).toMillis());

            for (String tableName : TABLES) {
                System.out.println("Table: " + tableName);

                final String dataURL = s3.generatePresignedUrl(BUCKET, PREFIX + tableName + ".json", expiration).toString();
                final String schemaURL = s3.generatePresignedUrl(BUCKET, PREFIX + tableName + "_schema.json", expiration).toString();
                final String query = String.format("""
                    IMPORT INTO %s
                    AVRO DATA (?)
                    WITH
                         data_as_json_records,
                         schema_uri = ?
                    """, tableName);

                try (PreparedStatement pstmt = conn.prepareStatement(query)) {
                    pstmt.setString(1, dataURL);
                    pstmt.setString(2, schemaURL);

                    try (ResultSet rs = pstmt.executeQuery()) {
                        final ResultSetMetaData metaData = rs.getMetaData();

                        while (rs.next()) {
                            for (int i = 1; i <= metaData.getColumnCount(); i++) {
                                System.out.println(metaData.getColumnLabel(i) + ": " + rs.getString(i));
                            }
                        }
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                    errors.add(tableName);
                }

                System.out.println("-----------------------");
            }
        }

        System.out.println("Errors: " + errors);
    }
}
